import{_ as s,C as l,o as d,c as e,j as i,a as t,E as n,a3 as r}from"./chunks/framework.C6R8kWFE.js";const O=JSON.parse(`{"title":"3-dars (Mentor). Foydalanuvchi tadqiqotlari: nega, qanday usullar va persona","description":"","frontmatter":{"title":"3-dars (Mentor). Foydalanuvchi tadqiqotlari: nega, qanday usullar va persona","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"week":{"n":1,"link":"/mentor/9-sinf/hafta-01/"},"g":3,"title":"Foydalanuvchi tadqiqotlari: nega, qanday usullar va persona","lead":"Yaxshi dizayner chizishdan oldin so'raydi, kuzatadi va tinglaydi. Bugun siz sinfdoshingizdan haqiqiy intervyu olasiz va uning «portreti» (persona) ni yasaysiz.","slide":"/slaydlar/9-sinf/hafta-01/dars-3.html","test":"/slaydlar/9-sinf/hafta-01/dars-3-test.html","student_link":"/9-sinf/hafta-01/dars-3","tabs":[{"g":1,"link":"/mentor/9-sinf/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf/hafta-01/dars-3","current":true}],"prev":{"g":2,"title":"UX/UI dizayn tamoyillari va jarayoni: yaxshi dizayn qanday bo'ladi","link":"/mentor/9-sinf/hafta-01/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf/hafta-01/dars-3.md","filePath":"mentor/9-sinf/hafta-01/dars-3.md"}`),h={name:"mentor/9-sinf/hafta-01/dars-3.md"},u={class:"blk"},m={id:"_1-dars-rejasi",tabindex:"-1"},q={class:"blk"},y={id:"_2-konspekt",tabindex:"-1"},v={class:"blk"},g={id:"_3-mini-intervyu-uchun-namuna-mentor-uchun-shablon",tabindex:"-1"},k={class:"blk"},b={id:"_4-amaliy-topshiriqlar",tabindex:"-1"},f={class:"blk"},p={id:"_5-tezkor-nazorat",tabindex:"-1"},c={class:"blk"},z={id:"_6-uyga-vazifa",tabindex:"-1"},_={class:"blk"},x={id:"mentor-uchun-izoh",tabindex:"-1"};function j(T,a,I,S,P,M){const o=l("Icon");return d(),e("div",null,[a[21]||(a[21]=i("p",null,[i("strong",null,"Hafta:"),t(" 1 · "),i("strong",null,"Davomiyligi:"),t(" 80 daqiqa · "),i("strong",null,"Turi:"),t(" nazariya + amaliyot (dizayn tadqiqoti) · "),i("strong",null,"I-bob"),t(", 3-dars")],-1)),a[22]||(a[22]=i("blockquote",null,[i("p",null,"Dasturda «Foydalanuvchi tadqiqotlari va ssenariy yaratish usullari» mavzusiga 2 dars ajratilgan (3–4). Bo'linish: 3-dars: nega tadqiqot kerak, tadqiqot usullari, persona va ehtiyojlar; 4-dars (2-hafta): ssenariy, foydalanuvchi oqimi (user flow) va journey map.")],-1)),i("div",u,[i("h2",m,[n(o,{name:"file-text"}),a[0]||(a[0]=t(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r('<p><strong>Maqsad:</strong> o&#39;quvchi foydalanuvchini o&#39;rganish nega kerakligini tushuntiradi, oltita asosiy tadqiqot usulini ajratadi, sinfdoshidan mini-intervyu oladi va natijadan persona kartasini tuzadi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>User Research ta&#39;rifini va maqsadini biladi.</li><li>So&#39;rovnoma, intervyu, kuzatuv, fokus guruh, testlash, ma&#39;lumot tahlilini bir-biridan ajratadi; sifat va miqdor farqini biladi.</li><li>Neytral va aniq savol yoza oladi.</li><li>Persona nima ekanini, undagi maydonlarni (demografiya, odat, motivatsiya, og&#39;riq nuqtalari, maqsad) biladi.</li><li>5 daqiqalik intervyu o&#39;tkazadi va persona kartasini to&#39;ldiradi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–5</td><td>Takrorlash</td><td>1–2-dars: UX va UI farqi (slayd 2)</td></tr><tr><td>5–30</td><td>Yangi mavzu 1</td><td>Nega tadqiqot (1-bo&#39;lim), oltita usul, so&#39;rovnoma, intervyu, kuzatuv (slaydlar 4–15)</td></tr><tr><td>30–35</td><td>Tanaffus</td><td></td></tr><tr><td>35–50</td><td>Yangi mavzu 2</td><td>Fokus guruh, testlash, usul tanlash, quiz, persona va ehtiyojlar (slaydlar 16–27)</td></tr><tr><td>50–75</td><td>Amaliyot</td><td>Mini-intervyu va persona kartasi (slayd 28)</td></tr><tr><td>75–80</td><td>Tezkor nazorat va xulosa</td><td></td></tr></tbody></table><p><strong>Vositalar:</strong> daftar va ruchka (yoki Figma/FigJam/Canva ixtiyoriy). Hech narsani o&#39;rnatish shart emas. Agar o&#39;quvchilar so&#39;rovnomani onlayn qilmoqchi bo&#39;lsa, Google Forms kerak bo&#39;ladi (Google akkaunt); buni qog&#39;ozda ham qilish mumkin.</p>',5))]),i("div",q,[i("h2",y,[n(o,{name:"file-text"}),a[3]||(a[3]=t(" 2. Konspekt ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-konspekt","aria-label":'Permalink to "<Icon name="file-text" /> 2. Konspekt"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_2-1-takrorlash-5-daqiqa" tabindex="-1">2.1. Takrorlash (5 daqiqa) <a class="header-anchor" href="#_2-1-takrorlash-5-daqiqa" aria-label="Permalink to &quot;2.1. Takrorlash (5 daqiqa)&quot;">​</a></h3><p>Savollar: UX nima? UI nima? Telegram&#39;da tugma yashirin bo&#39;lsa, bu UX muammosimi yoki UI? Ko&#39;prik: «Bugun birinchi qadam: dizayn chizishdan oldin kim uchun chizayotganimizni bilamiz.»</p><h3 id="_2-2-nega-tadqiqot-kerak" tabindex="-1">2.2. Nega tadqiqot kerak? <a class="header-anchor" href="#_2-2-nega-tadqiqot-kerak" aria-label="Permalink to &quot;2.2. Nega tadqiqot kerak?&quot;">​</a></h3><p>Dizayner ko&#39;pincha mahsulotni o&#39;ziga qarab chizadi: o&#39;zi uchun tushunarli, o&#39;ziga yoqadigan. Ammo foydalanuvchi boshqa odam: boshqa yosh, boshqa qurilma, boshqa sharoit. Tadqiqot dizayner taxmini bilan foydalanuvchi haqiqiy ehtiyoji o&#39;rtasidagi bo&#39;shliqni ko&#39;rsatadi.</p><p>O&#39;quv qo&#39;llanma bu fikrni shunday tasdiqlaydi: UX dizaynerlari o&#39;z auditoriyasini tushunishdan boshlaydi va dizayn qarorlariga asos bo&#39;ladigan tushunchalarni intervyu, so&#39;rov va foydalanish imkoniyatlari testi orqali to&#39;playdi. Wireframe bobida ham xato sifatida «foydalanuvchi ehtiyojlarini e&#39;tiborsiz qoldirish» keltirilgan: u maqsadli auditoriyaga mos kelmaydigan interfeysga olib keladi.</p><p><strong>Foydalanuvchi tadqiqoti (User Research)</strong> — foydalanuvchining ehtiyoji, muammosi, odatlari va mahsulotdan foydalanish tajribasini o&#39;rganish. (Qo&#39;llanmada bu atamaning to&#39;liq ta&#39;rifi alohida berilmagan, savollar ro&#39;yxatida bor; yuqoridagi ta&#39;rif qo&#39;llanmadagi usul tavsiflaridan umumlashtirildi.)</p><p><strong>Qachon?</strong> Loyiha boshida (kim uchun?), wireframe/prototipda (tushunarlimi?), tayyor mahsulotda (qanday ishlatilyapti?). Chizmada tuzatish kod yozilgandan keyin tuzatishdan arzon.</p><h3 id="_2-3-oltita-usul-o-quv-qo-llanma-1-2" tabindex="-1">2.3. Oltita usul (o&#39;quv qo&#39;llanma, 1.2) <a class="header-anchor" href="#_2-3-oltita-usul-o-quv-qo-llanma-1-2" aria-label="Permalink to &quot;2.3. Oltita usul (o&#39;quv qo&#39;llanma, 1.2)&quot;">​</a></h3><p>Qo&#39;llanmada keltirilgan asosiy usullar: so&#39;rovnoma (Survey), intervyu (Interview), kuzatuv (Observation), fokus guruhlar (Focus groups), testlash (Usability testing), foydalanuvchi ma&#39;lumotlarini tahlil qilish (Data analysis).</p><table tabindex="0"><thead><tr><th>Usul</th><th>Mohiyati</th><th>Natija turi</th><th>Eslatma</th></tr></thead><tbody><tr><td>So&#39;rovnoma</td><td>Savollar majmuasi; ko&#39;p odamdan qisqa vaqtda</td><td>Miqdor</td><td>Onlayn: Google Forms, SurveyMonkey, Typeform; savollar neytral va aniq bo&#39;lishi kerak</td></tr><tr><td>Intervyu</td><td>Bevosita suhbat; ehtiyoj, muammo, odat, motivatsiya, his-tuyg&#39;u</td><td>Sifat</td><td>Odatda yarim tuzilgan: tayyor savollar bor, kerak bo&#39;lsa yangi savol beriladi; persona uchun asos</td></tr><tr><td>Kuzatuv</td><td>Tabiiy sharoitda foydalanishni ko&#39;rish: qayerda qiynaldi, qayerda chalkashdi</td><td>Sifat</td><td>Faol (tadqiqotchi ishtirok etadi) yoki passiv (faqat ko&#39;radi); odam o&#39;zi sezmagan muammoni ko&#39;rsatadi</td></tr><tr><td>Fokus guruh</td><td>5–10 kishi, moderator boshqaradi</td><td>Sifat</td><td>Yangi g&#39;oyani baholash, variantlarni solishtirish; ayrimlar boshqalarga ta&#39;sir qiladi</td></tr><tr><td>Testlash (usability)</td><td>Prototip/mahsulot beriladi, topshiriq bajariladi</td><td>Ikkalasi</td><td>Kamchilik, chalkash element, murakkab navigatsiya topiladi</td></tr><tr><td>Ma&#39;lumot tahlili</td><td>Kirish soni, sahifada o&#39;tgan vaqt, bosilgan tugmalar, foydalanuvchi oqimlari</td><td>Miqdor</td><td>Haqiqiy xatti-harakat haqida raqam beradi</td></tr></tbody></table><p><strong>Sifat va miqdor.</strong> So&#39;rovnoma tajribani miqdoriy (quantitative) o&#39;lchaydi; intervyu natijalari sifat jihatdan (qualitative) tahlil qilinadi. Sodda qilib: miqdor «qancha?», sifat «nega?» savoliga javob beradi. Yaxshi tadqiqot ikkalasini birlashtiradi.</p><h3 id="_2-4-savol-tuzish-so-rovnoma-va-intervyu" tabindex="-1">2.4. Savol tuzish (so&#39;rovnoma va intervyu) <a class="header-anchor" href="#_2-4-savol-tuzish-so-rovnoma-va-intervyu" aria-label="Permalink to &quot;2.4. Savol tuzish (so&#39;rovnoma va intervyu)&quot;">​</a></h3><p>Yaxshi savol: neytral (javobga undamaydi), aniq (bitta narsa so&#39;raydi), tushunarli.</p><table tabindex="0"><thead><tr><th>Yomon</th><th>Nega yomon</th><th>Yaxshi</th></tr></thead><tbody><tr><td>«Bizning ilova juda qulay, shunday emasmi?»</td><td>Javobga undaydi</td><td>«Ilovada qidirish qanchalik oson? (1–5)»</td></tr><tr><td>«Ilovani tez-tez va yoqimli ishlatasizmi?»</td><td>Bir savolda ikki narsa</td><td>«Haftada necha marta ishlatasiz?»</td></tr><tr><td>«Sizga tez ilova kerakmi?»</td><td>«Tez» noaniq; javob doim «ha»</td><td>«Kitobni topish necha daqiqa oladi?»</td></tr></tbody></table><p>Intervyuda: ochiq savollar («Oxirgi marta kitobni qanday qidirdingiz?»), «nega?» bilan chuqurlashish, kam gapirib ko&#39;p tinglash, maslahat bermaslik.</p><h3 id="_2-5-testlash-va-ko-rsatkichlar" tabindex="-1">2.5. Testlash va ko&#39;rsatkichlar <a class="header-anchor" href="#_2-5-testlash-va-ko-rsatkichlar" aria-label="Permalink to &quot;2.5. Testlash va ko&#39;rsatkichlar&quot;">​</a></h3><p>Test rejasi (qo&#39;llanma): maqsad (qaysi ssenariyni sinaymiz), foydalanuvchi guruhi (yosh, tajriba, maqsad), topshiriqlar (kitob topish, yuklash), baholash mezonlari (bajarish vaqti, bosishlar soni, qoniqish). Ko&#39;rsatkichlar: vazifani muvaffaqiyatli bajarish foizi, vaqt, xatolar soni, foydalanuvchi fikri. Testlash bilan chuqur II-bobda (InVision) ishlaymiz; bugun faqat tushuncha.</p><h3 id="_2-6-persona-va-ehtiyojlar" tabindex="-1">2.6. Persona va ehtiyojlar <a class="header-anchor" href="#_2-6-persona-va-ehtiyojlar" aria-label="Permalink to &quot;2.6. Persona va ehtiyojlar&quot;">​</a></h3><p>Persona — tadqiqot ma&#39;lumotlaridan yig&#39;ilgan, ideal foydalanuvchining batafsil profili (xayoliy ism bilan, lekin real faktlardan). Qo&#39;llanmaga ko&#39;ra profilga qo&#39;shiladi: demografiya, psixografiya, xatti-harakat, motivatsiya va og&#39;riq nuqtalari. Intervyu natijalari persona uchun asos.</p><p>Ehtiyojni ko&#39;rish uchun uchta savol (qo&#39;llanma, ssenariy 1–3-qadamlari):</p><ul><li><strong>Kontekst:</strong> foydalanuvchi qayerda, qachon, qanday sharoitda ishlatadi (jismoniy, raqamli, ijtimoiy muhit).</li><li><strong>Og&#39;riq nuqtalari:</strong> hozirgi sharoitda duch keladigan qiyinchilik va umidsizliklar.</li><li><strong>Maqsad:</strong> foydalanuvchi mahsulot bilan nimaga erishmoqchi.</li></ul><p><strong>Segmentatsiya:</strong> ehtiyoj, xatti-harakat va motivatsiyasi o&#39;xshash odamlarni guruhlash; har guruh uchun alohida persona.</p><p><strong>Misol (to&#39;qima, namuna uchun) — Madina, 15 yosh, 9-sinf.</strong> Odat: kitobni telefonda, Telegram orqali qidiradi. Motivatsiya: inshoga tezda manba topish. Og&#39;riq nuqtasi: kitob nomini aniq bilmaydi, qidiruv topmaydi. Maqsad: 5 daqiqada kerakli kitobni topish.</p><p><strong>Qo&#39;llanmadan misol (Mobile_Book):</strong> «Talaba Shaxnoza ilmiy maqola yozish uchun mobil ilovadan elektron kitob izlaydi. U kitob nomini qidiruv paneliga kiritadi, kerakli kitobni tanlaydi, tafsilotlarini o&#39;qib chiqadi va yuklab oladi.» Bu ehtiyojdan kelib chiqadigan ekranlar: qidiruv oynasi, kitoblar ro&#39;yxati, kitob tafsilot sahifasi, yuklab olish tugmasi, xatcho&#39;p va baholash tizimi.</p><p>Uslubiy ko&#39;rsatmadagi E-Kutubxona misolida uchta foydalanuvchi turi bor: o&#39;quvchi (darslik va badiiy kitob qidiradi), o&#39;qituvchi (o&#39;quvchilarga manba topadi), kutubxonachi/administrator (yangi kitob qo&#39;shadi). Bu segmentatsiya misoli.</p><blockquote><p>Bu darsda ssenariy yozish va journey map chizish YO&#39;Q: ular 4-darsning mavzusi. Bugun faqat ma&#39;lumot yig&#39;ish va persona.</p></blockquote>',26))]),i("div",v,[i("h2",g,[n(o,{name:"file-text"}),a[6]||(a[6]=t(" 3. Mini-intervyu uchun namuna (mentor uchun shablon) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-mini-intervyu-uchun-namuna-mentor-uchun-shablon","aria-label":'Permalink to "<Icon name="file-text" /> 3. Mini-intervyu uchun namuna (mentor uchun shablon)"'},"​",-1))]),a[8]||(a[8]=r('<p>Mavzu: «Telefonda dars materiali yoki kitob qidirish» (E-Kutubxona uchun).</p><table tabindex="0"><thead><tr><th>№</th><th>Savol</th><th>Turi</th></tr></thead><tbody><tr><td>1</td><td>Kitob yoki dars materiali kerak bo&#39;lganda birinchi nima qilasiz?</td><td>ochiq</td></tr><tr><td>2</td><td>Oxirgi marta nimani qidirgan edingiz? Qadamma-qadam aytib bering.</td><td>ochiq</td></tr><tr><td>3</td><td>Qayerda qiynalasiz yoki to&#39;xtab qolasiz?</td><td>og&#39;riq nuqtasi</td></tr><tr><td>4</td><td>Buni qaysi qurilmada va qayerda (uyda, yo&#39;lda) qilasiz?</td><td>kontekst</td></tr><tr><td>5</td><td>Ideal holatda bu qanday bo&#39;lardi?</td><td>maqsad</td></tr></tbody></table>',2))]),i("div",k,[i("h2",b,[n(o,{name:"file-text"}),a[9]||(a[9]=t(" 4. Amaliy topshiriqlar ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-amaliy-topshiriqlar","aria-label":'Permalink to "<Icon name="file-text" /> 4. Amaliy topshiriqlar"'},"​",-1))]),a[11]||(a[11]=r('<h3 id="oson-—-5-ta-ochiq-savol" tabindex="-1">Oson — 5 ta ochiq savol <a class="header-anchor" href="#oson-—-5-ta-ochiq-savol" aria-label="Permalink to &quot;Oson — 5 ta ochiq savol&quot;">​</a></h3><p>Sinfdoshingizdan telefonda dars materiali yoki kitobni qanday qidirishi haqida 5 ta ochiq savol yozing (5 daqiqa). <strong>Kutiladigan natija:</strong> 5 ta savol, hech biri «ha/yo&#39;q» bilan tugamaydi, javobga undamaydi. <strong>Yechim:</strong> Yuqoridagi 3-bo&#39;limdagi jadval namuna. Tekshirish: savolda «shunday emasmi?», «juda» kabi undovchi so&#39;z yo&#39;q; har savolda bitta narsa so&#39;ralgan.</p><h3 id="o-rta-—-mini-intervyu" tabindex="-1">O&#39;rta — Mini-intervyu <a class="header-anchor" href="#o-rta-—-mini-intervyu" aria-label="Permalink to &quot;O&#39;rta — Mini-intervyu&quot;">​</a></h3><p>Juftlikda 5 daqiqalik intervyu oling, javoblarni jadvalga yozing (savol, javob, qiziq iqtibos), keyin rollarni almashtiring (10 daqiqa). <strong>Kutiladigan natija:</strong> to&#39;ldirilgan yozuv jadvali: kamida 5 savol va javob, 1–2 ta aniq iqtibos. <strong>Yechim namunasi:</strong></p><table tabindex="0"><thead><tr><th>Savol</th><th>Javob</th><th>Iqtibos</th></tr></thead><tbody><tr><td>Oxirgi marta nimani qidirdingiz?</td><td>Referat uchun «Amir Temur» haqida kitob</td><td>«Nomini aniq bilmasdim, 10 ta natija chiqdi»</td></tr><tr><td>Qayerda qiynaldingiz?</td><td>Qaysi biri kerakligini bilmadim</td><td>«Muqovasiga qarab tanladim»</td></tr></tbody></table><h3 id="qiyin-—-persona-kartasi" tabindex="-1">Qiyin — Persona kartasi <a class="header-anchor" href="#qiyin-—-persona-kartasi" aria-label="Permalink to &quot;Qiyin — Persona kartasi&quot;">​</a></h3><p>Intervyu yozuvlaridan persona kartasini tuzing (10 daqiqa): ism va yosh (xayoliy ism), odat, motivatsiya, og&#39;riq nuqtasi, maqsad va bitta iqtibos. <strong>Kutiladigan natija:</strong> bitta karta (A5 qog&#39;oz yoki Figma/Canva frame); har band intervyudagi javobdan kelib chiqadi. <strong>Yechim namunasi:</strong></p><ul><li><strong>Madina, 15 yosh.</strong> 9-sinf, Toshkent.</li><li><strong>Odat:</strong> kitobni telefonda qidiradi, ko&#39;pincha Telegram orqali.</li><li><strong>Motivatsiya:</strong> insho va referatga tez manba topish.</li><li><strong>Og&#39;riq nuqtasi:</strong> nomini aniq bilmaydi; qidiruv ko&#39;p natija chiqaradi.</li><li><strong>Maqsad:</strong> 5 daqiqada kerakli kitobni topish.</li><li><strong>Iqtibos:</strong> «Nomini aniq bilmasdim, 10 ta natija chiqdi.»</li></ul><p><strong>Tekshirish mezoni:</strong> persona o&#39;ylab topilmagan, har band intervyuda aytilgan; kartada «hamma uchun» degan umumiy gap yo&#39;q.</p><h3 id="bonus-kuchli-o-quvchi-uchun-—-ikkinchi-persona" tabindex="-1">Bonus (kuchli o&#39;quvchi uchun) — Ikkinchi persona <a class="header-anchor" href="#bonus-kuchli-o-quvchi-uchun-—-ikkinchi-persona" aria-label="Permalink to &quot;Bonus (kuchli o&#39;quvchi uchun) — Ikkinchi persona&quot;">​</a></h3><p>Shu mahsulot (E-Kutubxona) uchun boshqa segment persona&#39;si: o&#39;qituvchi yoki kutubxonachi. <strong>Yechim:</strong> o&#39;qituvchi: maqsad, o&#39;quvchilarga manbani tez tavsiya qilish; og&#39;riq nuqtasi: kitob ro&#39;yxatini har safar qo&#39;lda yig&#39;adi. Kutubxonachi: maqsad, yangi kitoblarni tez qo&#39;shish; og&#39;riq nuqtasi: ma&#39;lumotni qo&#39;lda kiritish.</p>',11))]),i("div",f,[i("h2",p,[n(o,{name:"file-text"}),a[12]||(a[12]=t(" 5. Tezkor nazorat ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-nazorat","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor nazorat"'},"​",-1))]),a[14]||(a[14]=r("<ol><li>User Research nima? <em>(Foydalanuvchining ehtiyoji, muammosi va tajribasini o&#39;rganish.)</em></li><li>Oltita usulni sanang. <em>(So&#39;rovnoma, intervyu, kuzatuv, fokus guruh, testlash, ma&#39;lumot tahlili.)</em></li><li>Qaysi usul «nega?» savoliga, qaysi biri «qancha?» savoliga javob beradi? <em>(Intervyu/kuzatuv: nega; so&#39;rovnoma/ma&#39;lumot tahlili: qancha.)</em></li><li>«Bizning ilova qulay, shunday emasmi?» savolida nima xato? <em>(Javobga undaydi, neytral emas.)</em></li><li>Persona nima va qaysi ma&#39;lumotlardan tuziladi? <em>(Ideal foydalanuvchining batafsil profili; intervyu, so&#39;rovnoma, kuzatuv natijalaridan.)</em></li></ol>",1))]),i("div",c,[i("h2",z,[n(o,{name:"file-text"}),a[15]||(a[15]=t(" 6. Uyga vazifa ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-uyga-vazifa","aria-label":'Permalink to "<Icon name="file-text" /> 6. Uyga vazifa"'},"​",-1))]),a[17]||(a[17]=i("p",null,[i("code",null,"uyga-vazifa.md"),t(" dagi 3-topshiriq: kamida 3 ta odamdan (sinfdoshdan farqli: oila a'zosi yoki boshqa yoshdagi odam) 5 daqiqalik intervyu olish va bitta persona kartasini tuzish (20–30 daqiqa). Topshirish: daftardagi yozuv va karta (rasmga olingan skrinshot yoki foto).")],-1))]),i("div",_,[i("h2",x,[n(o,{name:"file-text"}),a[18]||(a[18]=t(" Mentor uchun izoh ",-1)),a[19]||(a[19]=i("a",{class:"header-anchor",href:"#mentor-uchun-izoh","aria-label":'Permalink to "<Icon name="file-text" /> Mentor uchun izoh"'},"​",-1))]),a[20]||(a[20]=i("ul",null,[i("li",null,"Persona namunasidagi «Madina» va 60% kabi raqamlar to'qima (namuna uchun); haqiqiy tadqiqot natijasi emas deb ayting."),i("li",null,"Kuzatuv va intervyu faqat sinfdosh/oila a'zosining roziligi bilan: ismni yozishdan oldin so'rang."),i("li",null,"Hujjatlarda persona kartasining aniq shabloni, «Fokus guruh» uchun savollar ro'yxati va journey map yo'q; ular 4-darsga yoki mentorning qarori bilan.")],-1))])])}const U=s(h,[["render",j]]);export{O as __pageData,U as default};
